package com.example.order;

import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface OrderRepository extends JpaRepository<Order, Long> {
    @Query(value = "SELECT * FROM orders WHERE customer_id = :customerId AND status = 'PAID'", nativeQuery = true)
    List<Order> findPaid(@Param("customerId") String customerId);
}

package com.example.order;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;

@DataJpaTest
class OrderRepositoryTest {
    @Autowired
    OrderRepository orders;

    @Test
    void findsPaidOrdersOfCustomer() {
        orders.save(new Order(42L, OrderStatus.PAID));
        orders.save(new Order(42L, OrderStatus.CANCELLED));
        orders.save(new Order(7L, OrderStatus.PAID));

        assertThat(orders.findPaid("42")).hasSize(1);
    }
}

